-- =====================================================================
-- 015: format baru Surat Keterangan Tidak Mampu (SKTM) sesuai contoh desa:
--   biodata orang tua (+ golongan darah) → keterangan tidak mampu → data anak (sekolah, kelas, tujuan).
-- Surat lama tidak berubah (skema & redaksi tersnapshot di surat). versi naik.
-- Skema & redaksi sudah lolos validate_skema + clean_template. Bisa juga diubah lagi lewat wizard admin.
-- =====================================================================
UPDATE jenis_surat SET
  skema_form = '{"layout": "keterangan", "sections": [{"key": "orang_tua", "label": "Data Orang Tua", "type": "penduduk", "tampilkan": ["nama", "ttl", "jenis_kelamin", "kewarganegaraan", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "orang_tua_lain", "label": "Data Tambahan Orang Tua", "type": "fields", "fields": [{"key": "golongan_darah", "label": "Golongan darah", "type": "text"}]}, {"key": "anak", "label": "Data Anak", "type": "penduduk", "tampilkan": ["nama", "ttl", "jenis_kelamin"]}, {"key": "data_anak", "label": "Data Sekolah & Tujuan", "type": "fields", "fields": [{"key": "sekolah", "label": "Sekolah di", "type": "text", "required": true}, {"key": "kelas", "label": "Kelas/Semester", "type": "text", "required": true}, {"key": "keperluan", "label": "Tujuan", "type": "text", "required": true, "register": true}]}]}'::jsonb,
  template_isi = '<p>Yang bertanda tangan di bawah ini {{ ttd.jabatan }} {{ desa.nama }}, Kecamatan {{ desa.kecamatan }}, Kabupaten {{ desa.kabupaten }}, menerangkan dengan sebenarnya bahwa:</p><table><tbody><tr><td style="width:50mm">Nama</td><td style="width:4mm">:</td><td>{{ orang_tua.nama }}</td></tr><tr><td style="width:50mm">Tempat/Tgl. Lahir</td><td style="width:4mm">:</td><td>{{ orang_tua.ttl }}</td></tr><tr><td style="width:50mm">Jenis Kelamin</td><td style="width:4mm">:</td><td>{{ orang_tua.jenis_kelamin }}</td></tr><tr><td style="width:50mm">Warganegara</td><td style="width:4mm">:</td><td>{{ orang_tua.kewarganegaraan }}</td></tr><tr><td style="width:50mm">Golongan Darah</td><td style="width:4mm">:</td><td>{{ golongan_darah or ''-'' }}</td></tr><tr><td style="width:50mm">Agama</td><td style="width:4mm">:</td><td>{{ orang_tua.agama }}</td></tr><tr><td style="width:50mm">Status Perkawinan</td><td style="width:4mm">:</td><td>{{ orang_tua.status_perkawinan }}</td></tr><tr><td style="width:50mm">Pekerjaan</td><td style="width:4mm">:</td><td>{{ orang_tua.pekerjaan }}</td></tr><tr><td style="width:50mm">Alamat</td><td style="width:4mm">:</td><td>{{ orang_tua.alamat }}</td></tr></tbody></table><p>Nama tersebut di atas memang benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}, sepanjang pengetahuan kami yang bersangkutan memang benar keadaannya tidak mampu/miskin.</p><p>Surat keterangan ini diberikan kepada anaknya:</p><table><tbody><tr><td style="width:50mm">Nama</td><td style="width:4mm">:</td><td>{{ anak.nama }}</td></tr><tr><td style="width:50mm">Tempat/Tgl. Lahir</td><td style="width:4mm">:</td><td>{{ anak.ttl }}</td></tr><tr><td style="width:50mm">Jenis Kelamin</td><td style="width:4mm">:</td><td>{{ anak.jenis_kelamin }}</td></tr><tr><td style="width:50mm">Sekolah di</td><td style="width:4mm">:</td><td>{{ sekolah }}</td></tr><tr><td style="width:50mm">Kelas/Semester</td><td style="width:4mm">:</td><td>{{ kelas }}</td></tr><tr><td style="width:50mm">Tujuan</td><td style="width:4mm">:</td><td>{{ keperluan }}</td></tr></tbody></table><p>Demikian surat keterangan ini kami buat dengan sebenarnya untuk dapat dipergunakan sebagaimana mestinya.</p>',
  versi = versi + 1
WHERE code = 'SKTM';
